<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigDcrAllowedAuthMethodsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigDcrAllowedAuthMethodsAccessor trait.
 *
 * Covers null default, string/VO assignment via withDcrAllowedAuthMethods,
 * getDcrAllowedAuthMethods/dcrAllowedAuthMethods accessors, and isDcrAllowedAuthMethodsChanged with/without original.
 */
class TenantConfigDcrAllowedAuthMethodsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDcrAllowedAuthMethods creates a new instance with the DcrAllowedAuthMethods set
     * from a string value, and getDcrAllowedAuthMethods returns the primitive string.
     */
    public function testWithDcrAllowedAuthMethodsFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDcrAllowedAuthMethodsAccessorUnitTest();

        // Act
        $result = $holder->withDcrAllowedAuthMethods('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDcrAllowedAuthMethods());
    }
    /**
     * Asserts that withdcrAllowedAuthMethods has access to the value object
     * from a string value, and getDcrAllowedAuthMethods returns the primitive string.
     */
    public function testWithDcrAllowedAuthMethodsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDcrAllowedAuthMethodsAccessorUnitTest();

        // Act
        $result = $holder->withDcrAllowedAuthMethods('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->dcrAllowedAuthMethods()->value());
    }
    public function testChangedDcrAllowedAuthMethods(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDcrAllowedAuthMethodsAccessorUnitTest();
        $original = $holder->withDcrAllowedAuthMethods('one');
        $same = $holder->withDcrAllowedAuthMethods('one');
        $modified = $holder->withDcrAllowedAuthMethods('other');

        // Act
        $unchanged = $holder->isDcrAllowedAuthMethodsChanged();
        $withSame = $original->isDcrAllowedAuthMethodsChanged($same);
        $withDiferent = $original->isDcrAllowedAuthMethodsChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigDcrAllowedAuthMethodsAccessorUnitTest
{
    use TenantConfigDcrAllowedAuthMethodsAccessor;
}
